def to_base_negative_two(n):
 if n==0:return '0'
 digits=[]
 while n:
  n,remainder=divmod(n,-2)
  if remainder<0:n+=1;remainder+=2
  digits.append(str(remainder))
 return ''.join(reversed(digits))

